CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER)
IS
  l_total     NUMBER := 0;
  l_max_no    NUMBER;
  l_new_no    NUMBER;
  l_new_price NUMBER;
BEGIN
  /* Running total of original prices for considered wines */
  SELECT NVL(SUM("Price"), 0)
    INTO l_total
    FROM "wine"
   WHERE "Score" >= arg1;

  /* Rule 1: grape starts with prefix_ */
  UPDATE "wine"
     SET "Price" = arg3
   WHERE "Score" >= arg1
     AND NVL(INSTR("Grape", 'prefix_'), 0) = 1;

  /* Rule 2: otherwise, wine number strictly less than arg4 -> delete */
  DELETE FROM "wine"
   WHERE "Score" >= arg1
     AND NVL(INSTR("Grape", 'prefix_'), 0) <> 1
     AND "No" < arg4;

  /* Rule 3: otherwise, winery exactly Twomey -> price = arg3 + original price */
  UPDATE "wine"
     SET "Price" = arg3 + "Price"
   WHERE "Score" >= arg1
     AND NVL(INSTR("Grape", 'prefix_'), 0) <> 1
     AND "No" >= arg4
     AND "Winery" = 'Twomey';

  /* Rule 4: otherwise, Hollander concession (Cases > Score) -> price = arg3 + original price */
  UPDATE "wine"
     SET "Price" = arg3 + "Price"
   WHERE "Score" >= arg1
     AND NVL(INSTR("Grape", 'prefix_'), 0) <> 1
     AND "No" >= arg4
     AND ("Winery" <> 'Twomey' OR "Winery" IS NULL)
     AND "Cases" > "Score";

  /* Rule 5: otherwise -> price = 3 * arg3 */
  UPDATE "wine"
     SET "Price" = 3 * arg3
   WHERE "Score" >= arg1
     AND NVL(INSTR("Grape", 'prefix_'), 0) <> 1
     AND "No" >= arg4
     AND ("Winery" <> 'Twomey' OR "Winery" IS NULL)
     AND ("Cases" <= "Score" OR "Cases" IS NULL OR "Score" IS NULL);

  /* New row number */
  SELECT NVL(MAX("No"), 0)
    INTO l_max_no
    FROM "wine";

  IF l_max_no = 0 THEN
    l_new_no := 1;
  ELSE
    l_new_no := l_max_no + 1;
  END IF;

  IF l_total > arg4 THEN
    l_new_price := arg3 + 1;
  ELSE
    l_new_price := arg3;
  END IF;

  INSERT INTO "wine" ("No", "Score", "Grape", "Price")
  VALUES (l_new_no, arg1 + 1, 'prefix_' || arg2, l_new_price);
END;

